describe('User Logout - Secure Session Termination', () => {
  const testUser = {
    email: 'testuser@example.com',
    password: 'SecurePassword123!'
  };

  beforeEach(() => {
    cy.visit('/');
    cy.clearCookies();
    cy.clearLocalStorage();
    cy.session('login', () => {
      cy.visit('/login');
      cy.get('input[name="email"]').type(testUser.email);
      cy.get('input[name="password"]').type(testUser.password);
      cy.get('button[type="submit"]').click();
      cy.url().should('include', '/dashboard');
      cy.get('[data-testid="user-menu"]').should('be.visible');
    });
    cy.visit('/dashboard');
  });

  it('should successfully log out and terminate user session', () => {
    cy.get('[data-testid="user-menu"]').click();
    cy.get('[data-testid="logout-button"]').should('be.visible').click();

    cy.url().should('include', '/login');
    cy.get('h1').should('contain', 'Login');

    cy.getCookie('sessionToken').should('not.exist');
    cy.getCookie('authToken').should('not.exist');
    cy.window().then((win) => {
      expect(win.localStorage.getItem('userToken')).to.be.null;
    });
  });

  it('should prevent access to protected routes after logout', () => {
    cy.get('[data-testid="user-menu"]').click();
    cy.get('[data-testid="logout-button"]').click();
    cy.url().should('include', '/login');

    cy.visit('/dashboard', { failOnStatusCode: false });
    cy.url().should('include', '/login');
    cy.get('[data-testid="error-message"]').should('contain', 'Please log in');
  });

  it('should handle logout with confirmation modal', () => {
    cy.get('[data-testid="user-menu"]').click();
    cy.get('[data-testid="logout-button"]').click();

    cy.get('[data-testid="logout-confirmation-modal"]').should('be.visible');
    cy.get('[data-testid="confirm-logout-button"]').click();

    cy.url().should('include', '/login');
    cy.get('[data-testid="logout-success-message"]').should('contain', 'You have been logged out');
  });

  it('should cancel logout and remain logged in', () => {
    cy.get('[data-testid="user-menu"]').click();
    cy.get('[data-testid="logout-button"]').click();

    cy.get('[data-testid="logout-confirmation-modal"]').should('be.visible');
    cy.get('[data-testid="cancel-logout-button"]').click();

    cy.url().should('include', '/dashboard');
    cy.get('[data-testid="user-menu"]').should('be.visible');
    cy.getCookie('sessionToken').should('exist');
  });

  it('should clear all user data from local storage on logout', () => {
    cy.window().then((win) => {
      win.localStorage.setItem('userPreferences', JSON.stringify({ theme: 'dark' }));
      win.localStorage.setItem('userToken', 'test-token-123');
    });

    cy.get('[data-testid="user-menu"]').click();
    cy.get('[data-testid="logout-button"]').click();
    cy.get('[data-testid="confirm-logout-button"]').click();

    cy.window().then((win) => {
      expect(win.localStorage.getItem('userToken')).to.be.null;
      expect(win.localStorage.getItem('userPreferences')).to.be.null;
    });
  });

  it('should handle logout timeout gracefully', () => {
    cy.intercept('POST', '/api/logout', {
      delay: 5000,
      statusCode: 200,
      body: { success: true }
    }).as('logoutRequest');

    cy.get('[data-testid="user-menu"]').click();
    cy.get('[data-testid="logout-button"]').click();
    cy.get('[data-testid="confirm-logout-button"]').click();

    cy.get('[data-testid="loading-spinner"]').should('be.visible');
    cy.wait('@logoutRequest');
    cy.url().should('include', '/login');
  });

  it('should handle logout API failure and show error message', () => {
    cy.intercept('POST', '/api/logout', {
      statusCode: 500,
      body: { error: 'Server error' }
    }).as('logoutFailure');

    cy.get('[data-testid="user-menu"]').click();
    cy.get('[data-testid="logout-button"]').click();
    cy.get('[data-testid="confirm-logout-button"]').click();

    cy.wait('@logoutFailure');
    cy.get('[data-testid="error-message"]').should('contain', 'Failed to log out');
    cy.url().should('include', '/dashboard');
  });
});
